package com.naturalstreaming;
import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;
import org.springframework.beans.factory.annotation.Value;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
@Service public class Catalog {
 final JdbcTemplate db;final String key;Catalog(JdbcTemplate d,@Value("${ns.signing-key}")String k){db=d;key=k;if(k.length()<32)throw new IllegalArgumentException("Signing key too short");}
 public String sign(String value){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(m.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 public String seal(String s){return Base64.getUrlEncoder().withoutPadding().encodeToString(s.getBytes(StandardCharsets.UTF_8))+"."+sign(s);}
 public String unseal(String s,String error){try{String[] parts=s.split("\\.");String raw=new String(Base64.getUrlDecoder().decode(parts[0]),StandardCharsets.UTF_8);if(parts.length!=2||!MessageDigest.isEqual(sign(raw).getBytes(),parts[1].getBytes()))throw new IllegalArgumentException();return raw;}catch(Exception e){throw ApiError.fail(409,error);}}
 public long lockClock(){return db.queryForObject("SELECT revision FROM catalog_clock WHERE id=1 FOR UPDATE",Long.class);}
 public void event(String theme,Long account){long rev=lockClock()+1;db.update("UPDATE catalog_clock SET revision=? WHERE id=1",rev);db.update("INSERT INTO catalog_event(revision,theme_id,account_id) VALUES(?,?,?)",rev,theme,account);}
 public Map<String,Object> summary(Map<String,Object> row){var s=Json.read((String)row.get("scene_json"));Map<String,Object> m=new LinkedHashMap<>();m.put("id",row.get("id"));m.put("name",s.get("name"));m.put("version",row.get("current_version"));m.put("cover",s.get("cover"));m.put("description",s.getOrDefault("description",""));m.put("supportedModes",List.of("mix"));m.put("tracks",Json.objects(s.get("tracks")).stream().map(t->Map.of("id",t.get("id"),"label",t.get("label"),"description",t.get("description"))).toList());return m;}
 @Transactional(readOnly=true) public Map<?,?> sync(Auth.User u,String cursor){long now=db.queryForObject("SELECT revision FROM catalog_clock WHERE id=1 FOR SHARE",Long.class),since=-1;
  if(cursor!=null){String[] c=unseal(cursor,"cursor_invalid").split(":");try{if(c.length!=2||Long.parseLong(c[0])!=u.id())throw new IllegalArgumentException();since=Long.parseLong(c[1]);if(since<0||since>now)throw new IllegalArgumentException();}catch(Exception e){throw ApiError.fail(409,"cursor_invalid");}}
  var rows=db.queryForList("SELECT t.id,t.current_version,v.scene_json FROM theme t JOIN theme_version v ON v.theme_id=t.id AND v.version=t.current_version JOIN entitlement e ON e.theme_id=t.id AND e.account_id=? AND e.allowed=TRUE WHERE t.listed=TRUE ORDER BY t.id",u.id());
  Set<String> changed=new HashSet<>();if(since>=0)for(var e:db.queryForList("SELECT DISTINCT theme_id FROM catalog_event WHERE revision>? AND revision<=? AND (account_id IS NULL OR account_id=?)",since,now,u.id()))changed.add((String)e.get("theme_id"));
  List<Object> upserts=new ArrayList<>(),removed=new ArrayList<>();Set<String> visible=new HashSet<>();for(var r:rows){visible.add((String)r.get("id"));if(since<0||changed.contains(r.get("id")))upserts.add(summary(r));}
  for(var e:db.queryForList("SELECT e.theme_id,e.allowed FROM entitlement e WHERE e.account_id=?",u.id())){String id=(String)e.get("theme_id");if(!visible.contains(id)&&(since<0||changed.contains(id)))removed.add(Map.of("id",id,"reason",Auth.truth(e.get("allowed"))?"unpublished":"revoked"));}
  return Map.of("mode",since<0?"snapshot":"delta","cursor",seal(u.id()+":"+now),"upserts",upserts,"removed",removed);
 }
 public Map<String,Object> version(String theme,String version,boolean published){var r=db.queryForList("SELECT * FROM theme_version WHERE theme_id=? AND version=?"+(published?" AND state='published'":""),theme,version);if(r.isEmpty())throw ApiError.fail(404,"version_missing");return r.getFirst();}
 public Map<String,Object> lockVersion(String theme,String version){var r=db.queryForList("SELECT * FROM theme_version WHERE theme_id=? AND version=? FOR UPDATE",theme,version);if(r.isEmpty())throw ApiError.fail(404,"version_missing");return r.getFirst();}
 public Map<?,?> document(Map<String,Object> v){return Map.of("themeId",v.get("theme_id"),"version",v.get("version"),"state",v.get("state"),"revision",v.get("revision"),"scene",Json.read((String)v.get("scene_json")),"manifest",Json.read((String)v.get("manifest_json")),"license",Json.read((String)v.get("license_json")));}
}
